func Test_validate(t *testing.T) {
	tests := []struct {
		name       string
		constraint constraint
		wantErr    bool
	}{
		{
			name: "missing property",
			constraint: constraint{
				Operator: "eq",
				Value:    "bar",
			},
			wantErr: true,
		},
		{
			name: "missing operator",
			constraint: constraint{
				Property: "foo",
				Value:    "bar",
			},
			wantErr: true,
		},
		{
			name: "invalid operator",
			constraint: constraint{
				Property: "foo",
				Operator: "?",
				Value:    "bar",
			},
			wantErr: true,
		},
		{
			name: "valid",
			constraint: constraint{
				Property: "foo",
				Operator: "eq",
				Value:    "bar",
			},
		},
	}

	for _, tt := range tests {
		var (
			constraint = tt.constraint
			wantErr    = tt.wantErr
		)

		t.Run(tt.name, func(t *testing.T) {
			err := validate(constraint)

			if wantErr {
				require.Error(t, err)
				return
			}

			require.NoError(t, err)
		})
	}
}

func Test_matchesString(t *testing.T) {
	tests := []struct {
		name       string
		constraint constraint
		value      string
		wantMatch  bool
